    # your code
    pass

practice.solution:
def is_tree(n, edges):
    if len(edges) != n - 1:
        return 0
    adj = [[] for i in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    seen = [0] * n
    stack = [0]
    seen[0] = 1
    cnt = 1
    while stack:
        x = stack.pop()
        for y in adj[x]:
            if not seen[y]:
                seen[y] = 1
                cnt += 1
                stack.append(y)
    return 1 if cnt == n else 0

